function nav(path) {
  const selected = path.startsWith("/booking") || path.startsWith("/space") || path.startsWith("/reservations") || path.startsWith("/facility") ? "booking" :
    path.startsWith("/activities") ? "activities" : path.startsWith("/services") || path.startsWith("/visitors") || path.startsWith("/access") ? "services" : path === "/" ? "home" : "more";
  return `<nav class="bottom">
    <a class="${selected === "home" ? "on" : ""}" href="/"><span>${icon("house")}</span>首頁</a>
    <a class="${selected === "booking" ? "on" : ""}" href="/booking"><span>${icon("calendar-check")}</span>預約</a>
    <a class="${selected === "activities" ? "on" : ""}" href="/activities"><span>${icon("people-group")}</span>活動</a>
    <a class="${selected === "services" ? "on" : ""}" href="/services"><span>${icon("headset")}</span>服務</a>
    <a class="${selected === "more" ? "on" : ""}" href="/more"><span>${icon("grip")}</span>更多</a>
  </nav>`;
}

function profileAvatar() {
  return `<a class="profile-avatar" href="/account" aria-label="編輯帳戶資料" title="王小明的帳戶">王</a>`;
}

function top(title, back = "/") {
  if (!title) return `<header class="top"><div class="logo"><img class="brand-logo" src="data:image/png;base64," alt="南山人壽 NexSpace" width="291" height="56"></div><div style="flex:1"></div><a class="bell" href="/notifications" aria-label="通知中心">${icon("bell")}</a>${profileAvatar()}</header>`;
  return `<header class="top"><a class="back" href="${back}" aria-label="返回">${icon("chevron-left")}</a><div class="top-title">${title}</div><a class="bell" href="/notifications" aria-label="通知中心">${icon("bell")}</a>${profileAvatar()}</header>`;
}

function layout(path, title, body, back) {
  return `<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>${css}${accountCss}</style><div class="shell">${top(title, back)}${body}${nav(path)}</div>`;
}

